namespace t=aether::rendering::text;namespace q=t::truetype;
void repl(std::string& s,std::string a,std::string b){auto p=s.find(a);assert(p!=s.npos);s.replace(p,a.size(),b);}
void rect(std::vector<uint8_t>&p,int x,int y,int w,int h,unsigned rgb){for(int v=std::max(0,y);v<std::min(160,y+h);v++)for(int u=std::max(0,x);u<std::min(400,x+w);u++){size_t k=(v*400+u)*4;p[k]=rgb>>16;p[k+1]=rgb>>8;p[k+2]=rgb;p[k+3]=255;}}
struct G{std::shared_ptr<const t::GlyphMaskA8> m;int x,y;};
void glyphs(std::vector<uint8_t>&p,const std::vector<G>&gs,int ox,int oy){for(auto&g:gs)for(unsigned v=0;v<g.m->height;v++)for(unsigned u=0;u<g.m->width;u++){int x=ox+g.x+u,y=oy+g.y+v;if(x<0||y<0||x>=400||y>=160)continue;size_t k=(y*400+x)*4;unsigned a=g.m->bytes[v*g.m->stride+u];for(int c=0;c<3;c++)p[k+c]=(p[k+c]*(255-a)+127)/255;p[k+3]=a+(p[k+3]*(255-a)+127)/255;}}
void png(std::string path,const std::vector<uint8_t>&p){auto b=smoke_png::png(p,400,160);std::ofstream f(path,std::ios::binary);f.write((const char*)b.data(),b.size());assert(f);std::cout<<"PNG "<<path<<" bytes="<<b.size()<<" sha256="<<t::FontSource(b).digest<<"\n";}
int main(int argc,char**argv){assert(argc==4);std::string out=argv[1];std::ifstream font(argv[2],std::ios::binary|std::ios::ate);size_t n=font.tellg();font.seekg(0);auto source=t::FontSource::read_exact(font,n,"explicit local independent review font");auto binding=std::get<std::shared_ptr<const q::RealFontBinding>>(q::RealFontBinding::create(source,3072));std::ifstream in(argv[3]);std::vector<G> gs[3];std::int64_t widths[3]{};for(int i=0;i<3;i++){unsigned count;in>>count;for(unsigned j=0;j<count;j++){unsigned gid,phase;std::int64_t adv,pen;in>>gid>>adv>>pen>>phase;auto outline=std::get<std::shared_ptr<const q::Outline>>(binding->face()->outline(gid));auto mask=std::get<q::RasterOutput>(q::rasterize(outline,binding->font(),phase,0)).mask;gs[i].push_back({mask,int(pen/64+mask->bearing_left),int(16-mask->bearing_top)});widths[i]=pen+adv;}}assert(in);
std::vector<uint8_t> frames[2];unsigned over=0;for(auto&g:gs[0])for(unsigned v=0;v<g.m->height;v++)for(unsigned u=0;u<g.m->width;u++)if(g.y+int(v)>=16&&g.y+int(v)<32&&g.m->bytes[v*g.m->stride+u])over++;assert(over>0);std::cout<<"first_owner_nonzero_mask_pixels_in_second_line="<<over<<"\n";
for(int scene=0;scene<2;scene++){std::string html;for(int i=0;i<3;i++){auto css=q2c_cases::style();repl(css,"font-size:16px","font-size:48px");repl(css,"line-height:64px","line-height:16px");repl(css,"width:128px","width:300px");if(i==0)repl(css,"white-space:pre","white-space:nowrap");if(i==1)css+=";background-image:url(tile);background-repeat:no-repeat;background-position:0px 0px;background-size:auto";html+="<div id=\""+std::string(i==0?"z-first":i==1?"a-second":"m-empty")+"\" style=\""+css+"\">"+(i==0?" \tgy<!--join-->p\n ":i==1?"jgy":"<!--empty-->")+"</div>";}
std::string wrap="display:block;width:320px;height:auto;background-color:#f0e8d0";for(auto side:{"top","right","bottom","left"})wrap+=";margin-"+std::string(side)+":0px;padding-"+side+":32px;border-"+side+"-width:2px;border-"+side+"-style:solid;border-"+side+"-color:#804020";html=q2c_cases::document("<div id=\"wrapper\" style=\""+wrap+"\">"+html+"</div>");{std::ofstream f(out+"/scene"+std::to_string(scene+1)+".html");f<<html;}
std::vector<uint8_t> imagePixels(300*16*4);for(int y=0;y<16;y++)for(int x=0;x<300;x++){auto k=(y*300+x)*4;unsigned a=scene==0?128:255;unsigned r=(x/12%2)?224:40,g=(x/12%2)?64:160,b=80;imagePixels[k]=(b*a+127)/255;imagePixels[k+1]=(g*a+127)/255;imagePixels[k+2]=(r*a+127)/255;imagePixels[k+3]=a;}
auto resource=std::get<aether::rendering::preparation::ImageRef>(aether::rendering::preparation::ImageResource::copy(300,16,imagePixels));aether::rendering::NativeImageCatalog catalog{{"tile",resource}};
auto start=std::chrono::steady_clock::now();auto r=q::render_real_html_blocks_images(html,{"m-empty","a-second","z-first"},binding,{1024,1024},400,160,catalog);auto us=std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-start).count();if(auto*e=std::get_if<q::HtmlTextError>(&r)){std::cerr<<"render error="<<int(*e)<<"\n";return 2;}auto result=std::get<std::shared_ptr<const q::HtmlBlocksImagesFrame>>(r);auto* f=&result->blocks;assert(result->targets.size()==1);assert(result->targets[0].id=="a-second"&&result->targets[0].key=="tile");assert(result->targets[0].destination.x==34&&result->targets[0].destination.y==50&&result->targets[0].destination.width==300&&result->targets[0].destination.height==16);assert(result->work.unique_images==1&&result->work.unique_image_bytes==19200&&result->work.image_commands==1);assert(f->owners.size()==3);const char* ids[]={"z-first","a-second","m-empty"};for(int i=0;i<3;i++){auto&o=f->owners[i];assert(o.id==ids[i]);assert(o.text_box.content.x==34&&o.text_box.content.y==34+16*i&&o.text_box.content.height==16);assert(o.run->width_26_6==widths[i]);assert(o.run->source_text==(i==0?"gyp":i==1?"jgy":""));assert(o.has_command==(i!=2));std::cout<<"scene="<<scene+1<<" owner="<<o.id<<" origin="<<o.text_box.content.x<<","<<o.text_box.content.y<<" advance26_6="<<widths[i]<<" command="<<o.has_command<<":"<<o.command_index<<"\n";}
std::vector<uint8_t> expected(400*160*4,0);rect(expected,0,0,388,116,0x804020);rect(expected,2,2,384,112,0xf0e8d0);for(int i=0;i<3;i++){if(i==1)for(int y=0;y<16;y++)for(int x=0;x<300;x++){size_t src=(y*300+x)*4,dst=((50+y)*400+34+x)*4;unsigned a=imagePixels[src+3];for(int c=0;c<3;c++)expected[dst+c]=imagePixels[src+2-c]+(expected[dst+c]*(255-a)+127)/255;expected[dst+3]=a+(expected[dst+3]*(255-a)+127)/255;}glyphs(expected,gs[i],34,34+16*i);}
auto&own=frames[scene];own.resize(400*160*4);for(int y=0;y<160;y++)for(int x=0;x<400;x++){size_t k=(y*400+x)*4,j=y*f->frame.stride+x*4;own[k]=f->frame.pixels[j+2];own[k+1]=f->frame.pixels[j+1];own[k+2]=f->frame.pixels[j];own[k+3]=f->frame.pixels[j+3];}size_t diff=0,pixdiff=0;unsigned maxdiff=0;for(size_t k=0;k<own.size();k++){if(own[k]!=expected[k]){diff++;maxdiff=std::max(maxdiff,unsigned(abs(int(own[k])-int(expected[k]))));}}for(size_t k=0;k<own.size();k+=4)if(!std::equal(own.begin()+k,own.begin()+k+4,expected.begin()+k))pixdiff++;png(out+"/scene"+std::to_string(scene+1)+"_own.png",own);png(out+"/scene"+std::to_string(scene+1)+"_oracle.png",expected);std::cout<<"scene="<<scene+1<<" differing_channels="<<diff<<" differing_pixels="<<pixdiff<<" max_channel_diff="<<maxdiff<<" wall_us="<<us<<" native_glyph_commands="<<f->work.totals.native_glyph_commands<<" image_commands="<<f->work.totals.image_commands<<" canvas_pixels_reserved="<<f->work.canvas_pixels_reserved<<" mask_bytes_reserved="<<f->work.mask_reserved<<" registry_entries="<<f->work.totals.registry_entries<<std::endl;if(diff)return 3;}
size_t changed=0;for(size_t k=0;k<frames[0].size();k+=4)if(!std::equal(frames[0].begin()+k,frames[0].begin()+k+4,frames[1].begin()+k))changed++;assert(changed);std::cout<<"image_alpha_control_changed_pixels="<<changed<<"\n";rusage ru{};getrusage(RUSAGE_SELF,&ru);std::cout<<"process_maxrss_kib="<<ru.ru_maxrss<<" user_us="<<ru.ru_utime.tv_sec*1000000LL+ru.ru_utime.tv_usec<<" sys_us="<<ru.ru_stime.tv_sec*1000000LL+ru.ru_stime.tv_usec<<"\nindependent_geometry_FontTools_advances_manual_image_sourceover;shared_existing_A8_raster;NOT_BROWSER_PARITY;timings_single_instrumented_runs_not_benchmark;source_font_not_redistributed\n";}
